    // Vérifie si le nombre est premier
    let isPrime = true;
    for (let j = 2; j <= Math.sqrt(number); j++) {
      if (number % j === 0) {
        isPrime = false;
        break;
      }
    }

    // Si le nombre est premier, imprime-le sur la console
    if (isPrime) {
      console.log(`Le nombre premier trouvé est ${number}.`);
      return;
    }
  }
}

