#include <iostream>

template<typename T>
bool binarySearch(T* arr, size_t left, size_t right, const T& target) {
    while (left <= right) {
        size_t mid = (left + right) / 2;
        if (arr[mid] == target) {
            return true;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return false;
}

int main() {
    int arr[] = {1, 3, 5, 7, 9};
    size_t n = sizeof(arr) / sizeof(arr[0]);
    const int target = 7;

    if (binarySearch(arr, 0, n - 1, target)) {
        std::cout << "Element found in the array." << std::endl;
    } else {
        std::cout << "Element not found in the array." << std::endl;
    }

    return 0;
}
```

